    assert resp.json() == {
        "param": "123",
        "param2": ["456", "789"],
    }

if __name__ == "__main__":
    try:
        test_pass_extra_list()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
", "filepath": "reproduce_bug.py"}

